#!/usr/bin/env python3
"""Calibration: lambda_G (minimum over the subgroup generated by the constructed points) against
lambda_MW (minimum over the full, saturated Mordell-Weil lattice) for curves built xedni-style
through r small projective points plus O = (0:1:0).  [pcc:unverified]

Construction: shortest integer cubic (9 monomials, Y^3 coefficient 0) through r random points
(X:Y:Z) with |X|,|Y| <= e, 1 <= Z <= e; map to Weierstrass (xedni_cubic.cubic_to_weierstrass);
PARI ellminimalmodel, ellrank (with the constructed points), ellsaturation(B), heights / 2.
Only curves whose rank is determined (lower = upper bound) are used for lambda_MW.
"""
import sys, os, json, math, random, time, argparse
from fractions import Fraction
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import xedni_cubic as XC, xedni_toy as X0
import cypari2
from cysignals.alarm import alarm, AlarmInterrupt, cancel_alarm

pari = cypari2.Pari()
pari.allocatemem(10 ** 9)
pari.default("parisizemax", 3 * 10 ** 9)
pari.set_real_precision(120)


def fr(x):
    return pari(f"{x.numerator}/{x.denominator}")


def one(rng, r, e, sat, tlimit):
    pts = set()
    while len(pts) < r:
        X, Y, Z = rng.randint(-e, e), rng.randint(-e, e), rng.randint(1, e)
        g = math.gcd(math.gcd(X, Y), Z)
        pts.add((X // g, Y // g, Z // g))
    lifts = sorted(pts)
    rows = [XC.mono_vals(*L) for L in lifts]
    try:
        ker = X0.int_kernel(rows, 9)
    except AssertionError:
        return dict(status="kernel-rank")
    from flint import fmpz_mat
    red = [[int(v) for v in row] for row in fmpz_mat(ker).lll().tolist()]
    red.sort(key=lambda u: sum(v * v for v in u))
    cands = list(red)
    for _ in range(300):
        cf = [rng.randint(-1, 1) for _ in red]
        cands.append([sum(c * b[i] for c, b in zip(cf, red)) for i in range(9)])
    for u in cands:
        if not any(u):
            continue
        assert all(sum(a * b for a, b in zip(row, u)) == 0 for row in rows)
        cw, why = XC.cubic_to_weierstrass(u, lifts)
        if cw is None:
            continue
        W, ip = cw
        if X0.weier_invariants(*W)[-1] == 0:
            continue
        break
    else:
        return dict(status="no-good-cubic")
    rec = dict(r=r, e=e, u=u)
    try:
        alarm(tlimit)
        E = pari.ellinit(list(W))
        M = pari.ellminimalmodel(E)
        Mv = pari("(E)->my(v); ellminimalmodel(E, &v); v")(E)
        P = [pari.ellchangepoint([fr(x), fr(y)], Mv) for (x, y) in ip]
        for Q in P:
            assert pari.ellisoncurve(M, Q)
        D = abs(int(M[11]))
        rec["log_absDmin"] = math.log(D)
        GP = pari.ellheightmatrix(M, P) / 2
        hh = [float(GP[i, i]) for i in range(r)]
        rec["H"] = max(hh)
        dP = float(pari.matdet(GP))
        rec["detG_P"] = dP
        R = pari.ellrank(M, 1, P)
        rlo, rhi = int(R[0]), int(R[1])
        rec["rank_lo"], rec["rank_hi"] = rlo, rhi
        rec["tors"] = int(pari.elltors(M)[0])
        if dP > 1e-9 * max(1.0, max(hh)) ** r:
            mnP = pari.qfminim(GP, None, None, 2)
            rec["lambda_G"] = float(mnP[1])
        else:
            rec["lambda_G"] = None
            rec["dependent"] = True
        if rlo == rhi and len(R[3]) == rlo and rlo > 0:
            gens = pari.ellsaturation(M, R[3], sat)
            GM = pari.ellheightmatrix(M, gens) / 2
            mn = pari.qfminim(GM, None, None, 2)
            rec["lambda_MW"] = float(mn[1])
            rec["detG_MW"] = float(pari.matdet(GM))
            if rec["lambda_G"]:
                rec["rho_G"] = rec["H"] / rec["lambda_G"]
            rec["rho_MW"] = rec["H"] / rec["lambda_MW"]
            if rlo == r and rec.get("lambda_G"):
                rec["index"] = math.sqrt(dP / rec["detG_MW"])
        cancel_alarm()
        rec["status"] = "ok"
    except AlarmInterrupt:
        rec["status"] = "timeout"
    except Exception as ex:
        cancel_alarm()
        rec["status"] = "error:" + str(ex)[:80]
    return rec


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--r", default="2,3,4,5,6,7,8")
    ap.add_argument("--e", default="2,4,8,16")
    ap.add_argument("--n", type=int, default=12)
    ap.add_argument("--sat", type=int, default=100)
    ap.add_argument("--tlimit", type=int, default=60)
    ap.add_argument("--seed", type=int, default=20261115)
    ap.add_argument("--out", required=True)
    a = ap.parse_args()
    with open(a.out, "a") as fo:
        for e in [int(x) for x in a.e.split(",")]:
            for r in [int(x) for x in a.r.split(",")]:
                rng = random.Random(a.seed * 7919 + e * 101 + r)
                for j in range(a.n):
                    t0 = time.time()
                    rec = one(rng, r, e, a.sat, a.tlimit)
                    rec.update(r=r, e=e, j=j, sec=round(time.time() - t0, 2))
                    fo.write(json.dumps(rec, default=str) + "\n")
                    fo.flush()


if __name__ == "__main__":
    main()
